import React from "react";
import { FaLinkedin, FaGithub, FaEnvelope } from "react-icons/fa";

const Footer = () => {
  return (
    <>
      <style>{`
        .footer {
          position: relative;
          background: linear-gradient(135deg, #0f172a, #111827);
          color: #cbd5e1;
          padding: 30px 8%;
          text-align: center;
          overflow: hidden;
        }

        /* Subtle top glow line */
        .footer::before {
          content: "";
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 80%;
          height: 1px;
          background: linear-gradient(90deg, transparent, #2563eb, transparent);
        }

        .footer-name {
          font-size: 1.3rem;
          font-weight: 600;
          color: #ffffff;
          margin-bottom: 8px;
          letter-spacing: 0.5px;
        }

        .footer-tagline {
          font-size: 0.85rem;
          margin-bottom: 18px;
          color: #94a3b8;
        }

        .footer-icons {
          display: flex;
          justify-content: center;
          gap: 16px;
          margin-bottom: 18px;
        }

        .footer-icons a {
          width: 38px;
          height: 38px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.05);
          color: #cbd5e1;
          font-size: 1rem;
          transition: all 0.3s ease;
          backdrop-filter: blur(6px);
        }

        .footer-icons a:hover {
          background: #2563eb;
          color: #ffffff;
          transform: translateY(-4px) scale(1.05);
          box-shadow: 0 8px 20px rgba(37, 99, 235, 0.4);
        }

        .footer-copy {
          font-size: 0.75rem;
          color: #64748b;
        }

        @media (max-width: 768px) {
          .footer {
            padding: 25px 6%;
          }
        }
      `}</style>

      <footer className="footer">
        <div className="footer-name">Swetha</div>

        <div className="footer-tagline">
          Crafting scalable and impactful digital experiences.
        </div>

        <div className="footer-icons">
          <a href="mailto:swethaa1805@email.com">
            <FaEnvelope />
          </a>

          <a
            href="https://www.linkedin.com/in/swetha-a-0b1712382/"
            target="_blank"
            rel="noopener noreferrer"
          >
            <FaLinkedin />
          </a>

          <a
            href="https://github.com/Swethaa1805"
            target="_blank"
            rel="noopener noreferrer"
          >
            <FaGithub />
          </a>
        </div>

        <div className="footer-copy">
          © {new Date().getFullYear()} Swetha. All Rights Reserved.
        </div>
      </footer>
    </>
  );
};

export default Footer;
